C++.fragment:
size_t read_all() {
    std::ifstream f("data.txt");
    std::string text((std::istreambuf_iterator<char>(f)), std::istreambuf_iterator<char>());
    return text.size();
}

Go.fragment:
func read_all() (int, error) {
 f, err := os.Open("data.txt")
 if err != nil { return 0, err }
 defer f.Close()
 data, err := io.ReadAll(f)
 if err != nil { return 0, err }
 return len(data), nil
}

