def read_all():
    with open("data.txt") as f:
        text = f.read()
    return len(text)

Swift.fragment:
func readAll() throws -> Int {
    let handle = try FileHandle(forReadingFrom: URL(fileURLWithPath: "data.txt"))
    defer { handle.closeFile() }
    let text = handle.readDataToEndOfFile()
    return text.count
}

TypeScript.fragment:
function readAll(): number {
  const fd = openSync("data.txt", "r");
  try {
    const text = readFileSync(fd, "utf8");
    return text.length;
  } finally {
    closeSync(fd);
  }
}
